      "path": "reconcile/matcher.py",
      "content": "from __future__ import annotations

from collections import Counter
from typing import Iterable, List

from .models import Discrepancy, Row


def find_discrepancies(left_rows: Iterable[Row], right_rows: Iterable[Row]) -> list[Discrepancy]:
    # Build lookup maps for efficient matching
    left_map: dict[tuple[str, str], list[Row]] = {}
    for row in left_rows:
        key = (row.merchant_order_id, row.provider_txn_id)
        left_map.setdefault(key, []).append(row)

    right_map: dict[tuple[str, str], list[Row]] = {}
    for row in right_rows:
        key = (row.merchant_id, row.provider_txn_id)
        right_map.setdefault(key, []).append(row)

    discrepancies: list[Discrepancy] = []

    # Process left rows
    for (merchant_id, provider_txn_id), left_rows_list in left_map.items():
        if len(left_rows_list) > 1:
            # Duplicate in left
            for _ in left_rows_list:
                discrepancies.append(
                    Discrepancy(
                        kind="duplicate_left",
                        merchant_order_id=merchant_id,
                        provider_txn_id=provider_txn_id,
                        detail="",
                    )
                )
            continue
        left_row = left_rows_list[0]

        if (merchant_id, provider_txn_id) not in right_map:
            discrepancies.append(
                Discrepancy(
                    kind="missing_right",
                    merchant_order_id=merchant_id,
                    provider_txn_id=provider_txn_id,
                    detail="",
                )
            )
            continue

        # There is a matching right row; check amount
        right_row = right_map[(merchant_id, provider_txn_id)][0]
        if left_row.amount_cents != right_row.amount_cents:
            discrepancies.append(
                Discrepancy(
                    kind="amount_mismatch",
                    merchant_order_id=merchant_id,
                    provider_txn_id=provider_txn_id,
                    detail="",
                )
            )

    # Process right rows that have no counterpart in left
    for (merchant_id, provider_txn_id), right_rows_list in right_map.items():
        if (merchant_id, provider_txn_id) not in left_map:
            for _ in right_rows_list:
                discrepancies.append(
                    Discrepancy(
                        kind="missing_left",
                        merchant_order_id=merchant_id,
                        provider_txn_id=provider_txn_id,
                        detail="",
                    )
                )

    return discrepancies
